const input = $json || {};
const message = input.message || {};
const text = message.text || input.text || '';
const chatId = message.chat?.id || input.chat_id || input.chatId || '';

let symbol = 'XAU/USD';
let timeframe = '4H';
let notes = text;

// Supported command examples:
// /scan XAU/USD 4H price pulled back to 21 EMA after bullish break
// /scan EUR/USD 1H pin bar rejection at support
const cleaned = text.replace(/^\/scan/i, '').trim();
if (cleaned) {
  const parts = cleaned.split(/\s+/);
  if (parts[0] && /^[A-Z]{3}\/?[A-Z]{3}$|^XAU\/?USD$/i.test(parts[0])) {
    symbol = parts.shift().toUpperCase().replace('XAUUSD', 'XAU/USD');
    if (!symbol.includes('/') && symbol.length === 6) symbol = symbol.slice(0, 3) + '/' + symbol.slice(3);
  }
  if (parts[0] && /^(1H|4H|H1|H4)$/i.test(parts[0])) {
    timeframe = parts.shift().toUpperCase().replace('H1', '1H').replace('H4', '4H');
  }
  notes = parts.join(' ') || cleaned;
}

if (!notes || notes.toLowerCase() === '/scan') {
  notes = 'Manual smoke test: price is pulling back toward the 21 EMA after a strong move. Decide WATCH / WAIT / REJECT / A+ CANDIDATE. Do not invent live data.';
}

return [{
  json: {
    chat_id: chatId,
    rpc_payload: {
      symbol,
      timeframe,
      input_type: chatId ? 'telegram_group_notes' : 'manual_test',
      chart_notes: notes,
      ozzi_notes: 'Use Ozzi rules only: 4H 21 EMA break + retest, or 1H/4H pin bar rejection. Athens watch windows. Risk discipline $150-$200 only for high-quality setup. No auto-trading.',
      max_agents: 8,
      max_cross_questions: 6,
      agent_timeout_seconds: 120
    }
  }
}];

const rpc = $json;
const transcript = rpc.transcript || [];
const maxTelegram = 3900;

let text = rpc.telegram_text || '';
if (!text && transcript.length) {
  text = ['🏢 ForexAgents HQ — Team Debate'];
  for (const m of transcript) {
    text.push(`\n${m.emoji || '🤖'} ${m.display || m.agent_id} (${m.stage})\n${m.message || ''}`);
  }
  text = text.join('\n');
}

if (!text) text = 'ForexAgents RPC returned no debate text.';

const footer = `\n\n🧾 journal: ${rpc.journal_id || 'none'} | elapsed: ${rpc.elapsed_seconds || '?'}s`;
text = text + footer;

const chunks = [];
let remaining = text;
while (remaining.length > maxTelegram) {
  let cut = remaining.lastIndexOf('\n', maxTelegram);
  if (cut < 1000) cut = maxTelegram;
  chunks.push(remaining.slice(0, cut));
  remaining = remaining.slice(cut).trim();
}
chunks.push(remaining);

return chunks.map((chunk, index) => ({
  json: {
    chat_id: $('Build RPC Payload').first().json.chat_id,
    text: chunks.length > 1 ? `${chunk}\n\nPart ${index + 1}/${chunks.length}` : chunk,
    rpc_ok: rpc.ok,
    journal_id: rpc.journal_id
  }
}));
